create or replace function public.create_pending_b2b_order(p_buyer_id uuid,p_quote_id uuid,p_idempotency_key text) returns table(order_id uuid,total_amount numeric,currency char(3),status text) language plpgsql security definer set search_path=public,pg_temp as $$ declare v_quote public.business_rfq_quotes%rowtype; v_rfq public.business_rfqs%rowtype; v_product public.products%rowtype; v_order_id uuid; v_store_id uuid; v_total numeric; v_stock int; begin if p_buyer_id is null or p_quote_id is null or length(trim(p_idempotency_key))<16 then raise exception 'invalid_payload'; end if; select q.* into v_quote from public.business_rfq_quotes q where q.id=p_quote_id for update; if not found or v_quote.status<>'accepted' then raise exception 'quote_not_accepted'; end if; select r.* into v_rfq from public.business_rfqs r where r.id=v_quote.rfq_id for update; if not found or v_rfq.buyer_id<>p_buyer_id then raise exception 'buyer_mismatch'; end if; if v_quote.product_id is null then raise exception 'product_required'; end if; select p.* into v_product from public.products p where p.id=v_quote.product_id for update; if not found or not v_product.is_active then raise exception 'product_unavailable'; end if; select s.id into v_store_id from public.stores s where s.id=v_product.store_id and s.vendor_id=v_quote.supplier_id and s.is_active=true for update; if not found then raise exception 'supplier_product_mismatch'; end if; v_total:=round(v_quote.unit_price* v_rfq.quantity,2); v_stock:=coalesce(v_product.stock,0); if v_stock < v_rfq.quantity then raise exception 'insufficient_stock'; end if; select o.id into v_order_id from public.orders o where o.buyer_id=p_buyer_id and o.notes like '%b2b_idempotency:'||p_idempotency_key||'%' limit 1; if v_order_id is not null then return query select o.id,o.total_amount,o.currency,o.status from public.orders o where o.id=v_order_id; return; end if; insert into public.orders(buyer_id,status,currency,subtotal_amount,shipping_amount,discount_amount,tax_amount,total_amount,platform_commission,seller_amount,affiliate_commission,region,payment_status,notes,expires_at) values(p_buyer_id,'pending',upper(v_quote.currency),v_total,0,0,0,v_total,0,v_total,0,coalesce(v_rfq.delivery_country,'GLOBAL'),'pending','B2B RFQ '||v_rfq.id||' | b2b_idempotency:'||p_idempotency_key,now()+interval '30 minutes') returning id into v_order_id; insert into public.order_items(order_id,product_id,store_id,product_title,quantity,unit_price,subtotal) values(v_order_id,v_product.id,v_store_id,v_product.title,v_rfq.quantity,v_quote.unit_price,v_total); insert into public.inventory_reservations(order_id,product_id,quantity,status,reserved_at,expires_at) values(v_order_id,v_product.id,v_rfq.quantity,'reserved',now(),now()+interval '30 minutes'); update public.products set stock=stock-v_rfq.quantity,updated_at=now() where id=v_product.id; update public.inventory set available_quantity=greatest(available_quantity-v_rfq.quantity,0),reserved_quantity=reserved_quantity+v_rfq.quantity,updated_at=now() where product_id=v_product.id; insert into public.inventory_movements(product_id,order_id,movement_type,quantity,quantity_before,quantity_after,reason) values(v_product.id,v_order_id,'reservation',v_rfq.quantity,v_stock,v_stock-v_rfq.quantity,'B2B RFQ accepted'); update public.b2b_awards set status='ordered',order_id=v_order_id,updated_at=now() where quote_id=p_quote_id; update public.business_rfqs set status='closed',updated_at=now() where id=v_rfq.id; return query select o.id,o.total_amount,o.currency,o.status from public.orders o where o.id=v_order_id; end; $$;
revoke all on function public.create_pending_b2b_order(uuid,uuid,text) from public,anon,authenticated; grant execute on function public.create_pending_b2b_order(uuid,uuid,text) to service_role;
